fix(openai): allow providers to disable web search source includes (#20599)

## Background

https://github.com/vercel/ai/issues/18507

any OpenAI web-search tool automatically added
`web_search_call.action.source`. Bedrock Mantle reused this logic but
rejects that include value, breaking web search

## Summary

added an opt-out `includeWebSearchSources` which helps in setting an
internal provider capability flag

## End-to-End Verification

verified by running the following repro: 
<details>

```ts
import { createBedrockMantle } from '@ai-sdk/amazon-bedrock/mantle';
import { openai } from '@ai-sdk/openai';
import { parseJSON } from '@ai-sdk/provider-utils';
import assert from 'node:assert/strict';
import { generateText } from 'ai';
import { run } from '../../lib/run';

const unsupportedInclude = 'web_search_call.action.sources';

type RequestBody = {
  include?: string[];
  tools?: Array<{
    type: string;
    external_web_access?: boolean;
  }>;
};

const bedrockMantle = createBedrockMantle({
  region: 'us-east-1',
  apiKey: 'not-used',
  fetch: async (_url, options) => {
    const body = (await parseJSON({
      text: options!.body! as string,
    })) as RequestBody;

    console.log(
      'Relevant request fields:',
      JSON.stringify({ include: body.include, tools: body.tools }, null, 2),
    );

    // The web search tool itself is compatible with Bedrock Mantle.
    assert.deepEqual(body.tools, [
      {
        type: 'web_search',
        external_web_access: false,
      },
    ]);

    if (body.include?.includes(unsupportedInclude)) {
      // Reproduce the response returned by Bedrock Mantle for this include value.
      return new Response(
        JSON.stringify({
          error: {
            message:
              `Unsupported value: '${unsupportedInclude}' is not supported with the ` +
              "'openai.gpt-5.6-terra' model. Supported values are: " +
              "'reasoning.encrypted_content' and 'message.output_text.logprobs'.",
            type: 'invalid_request_error',
            param: 'include',
            code: 'unsupported_value',
          },
        }),
        {
          status: 400,
          headers: { 'content-type': 'application/json' },
        },
      );
    }

    return new Response(
      JSON.stringify({
        id: 'resp_test',
        object: 'response',
        created_at: 0,
        model: 'openai.gpt-5.6-terra',
        status: 'completed',
        error: null,
        incomplete_details: null,
        output: [
          {
            type: 'message',
            id: 'msg_1',
            role: 'assistant',
            status: 'completed',
            content: [
              {
                type: 'output_text',
                text: 'ok',
                annotations: [],
              },
            ],
          },
        ],
        usage: {
          input_tokens: 1,
          output_tokens: 1,
          total_tokens: 2,
        },
      }),
      { headers: { 'content-type': 'application/json' } },
    );
  },
});

run(async () => {
  const result = await generateText({
    model: bedrockMantle.responses('openai.gpt-5.6-terra'),
    tools: {
      web_search: openai.tools.webSearch({
        externalWebAccess: false,
      }),
    },
    prompt: 'What is the latest news about Amazon Bedrock?',
  });

  assert.equal(result.text, 'ok');
  console.log(
    'Verified: the unsupported web search source include was omitted.',
  );
});
```
</details>

